// Format a byte count for display:
//   below 1024            -> whole bytes, e.g. "512 B"
//   below 1024*1024       -> kibibytes with ONE decimal, e.g. "1.5 KB"
//   1024*1024 and above   -> mebibytes with ONE decimal, e.g. "2.0 MB"
export function formatBytes(n: number): string {
  if (n < 1024) {
    return `${n} B`;
  }
  if (n < 1024 * 1024) {
    return `${(n / 1024).toFixed(1)} KB`;
  }
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

reference_solution.test_bytesutil.ts:
import { formatBytes } from "./bytesutil";

function expectEqual(actual: string, expected: string, label: string): void {
  if (actual !== expected) {
    throw new Error(`${label}: got ${actual}, want ${expected}`);
  }
}

expectEqual(formatBytes(512), "512 B", "plain bytes");
expectEqual(formatBytes(1023), "1023 B", "just below KB boundary");
expectEqual(formatBytes(1024), "1.0 KB", "exactly the KB boundary");
expectEqual(formatBytes(1536), "1.5 KB", "fractional KB");
expectEqual(formatBytes(1048575), "1024.0 KB", "just below MB boundary");
expectEqual(formatBytes(1048576), "1.0 MB", "exactly the MB boundary");
expectEqual(formatBytes(2097152), "2.0 MB", "whole MB");

console.log("all formatBytes tests passed");

