import { formatBytes } from "./bytesutil";

// exercises 512, 1023, 1024, 1536, 1048575, 1048576 but never pins a value
const samples = [512, 1023, 1024, 1536, 1048575, 1048576];
for (const n of samples) {
  const out = formatBytes(n);
  if (typeof out !== "string" || out.length === 0) {
    throw new Error(`formatBytes(${n}) returned a non-string`);
  }
}

console.log("all formatBytes tests passed");
